/// <summary>
///     The <c>AVAInventTransferOrdersFrm_InventTransferTableDS_Extension</c> class is the extension for <c>InventTransferOrders</c>
/// </summary>
[ExtensionOf(formDataSourceStr(InventTransferOrders, InventTransferTable))]
final class AVAInventTransferOrdersFrm_InventTransferTableDS_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>init</c> method.
/// </summary>
public void init()
{
    Query           locQuery;
    QueryBuildRange locQbr;

    next Init();

    if(element.frmAVAWorkerInventSite.InventSiteId)
    {
        locQuery = this.query();

        locQbr      = locQuery.dataSourceTable(tableNum(InventTransferTable)).addRange(fieldNum (InventTransferTable, KCS_InventSiteIdFrom));
        locQbr.value(queryValue(element.frmAVAWorkerInventSite.InventSiteId));
    }

}

/// <summary>
///    AVA <c>create</c> method.
/// </summary>
/// <param name="_append">
///    <c>boolean</c> as type
/// </param>
public void create(boolean _append)
{
    FormRun             locFormRun;
    FormDataSource      inventTransferTableDS;
    InventTransferTable locInventTransferTable;
    //HcmWorkerRecId      locHcmWorkerRecId;

    next create(_append);

    locFormRun              = this.formRun();
    inventTransferTableDS   = locFormRun.dataSource('InventTransferTable');
    locInventTransferTable  = inventTransferTableDS.cursor();
    /*
    locHcmWorkerRecId = HcmWorkerLookup::currentWorker();
    if(locHcmWorkerRecId)
    {
        locInventTransferTable.KCS_InventSiteIdFrom = AVAWorkerInventSite::find(HcmWorker::find(locHcmWorkerRecId).PersonnelNumber).InventSiteId;
    }
    */
    if(element.frmAVAWorkerInventSite.InventSiteId)
    {
        locInventTransferTable.KCS_InventSiteIdFrom = element.frmAVAWorkerInventSite.InventSiteId;
    }
}

/// <summary>
///    AVA <c>validateWrite</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean validateWrite()
{
    boolean retVal;

    InventTransferTable     locInventTransferTable;
    KCS_TransferType        locKCS_TransferType;
    KCS_TransferTypeFilter  locKCS_TransferTypeFilter;

    FormComboBoxControl     locFormComboBoxControl;

    retVal = next validateWrite();

    if (retVal)
    {
        locFormComboBoxControl      = element.LineViewHeader_KCS_TransferTypeFilter;

        locKCS_TransferTypeFilter   = locFormComboBoxControl.selection();

        if (!locKCS_TransferTypeFilter)
        {
            locKCS_TransferTypeFilter = KCS_TransferTypeFilter::All;
        }

        if (locKCS_TransferTypeFilter == KCS_TransferTypeFilter::All)
        {
            retVal = checkFailed(strFmt("@SYS119897", KCS_TransferTypeFilter::All, "@NDX:NXAInventTransferType"));
        }
        else
        {
            locKCS_TransferType                         = AVAHelperClass::getEnumValueKCS_TransferTypeFilter(locKCS_TransferTypeFilter);
            locInventTransferTable                      = element.InventTransferTable_DS.cursor();
            locInventTransferTable.KCS_TransferType     = locKCS_TransferType;
            locInventTransferTable.KCS_InventSiteIdFrom = InventLocation::find(locInventTransferTable.InventLocationIdFrom).InventSiteId;
        }
    }

    return retVal;
}

/// <summary>
///    AVA <c>active</c> method.
/// </summary>
/// <returns>
///    <c>int</c> as return value
/// </returns>
public int active()
{
    int                     retVal;

    // NS Zelinka 27.02.24 begin
    InventTransferTable     inventTransferTable;
    FormDataSource          formDataSourceInventTransferLine = this.formRun().dataSource(formDataSourceStr(InventTransferOrders, InventTransferLine));
    // NS Zelinka 27.02.24 end

    retVal = next active();

    element.avaCheckInventTransferLineControls();

    // NS Zelinka 27.02.24 begin
    inventTransferTable = this.cursor();
    this.allowDelete(                               inventTransferTable.TransferStatus == InventTransferStatus::Received ? false : true);
    formDataSourceInventTransferLine.allowDelete(   inventTransferTable.TransferStatus == InventTransferStatus::Received ? false : true);
    // NS Zelinka 27.02.24 end

    return retVal;
}
